CREATE TABLE USUARIOS (ID BIGINT NOT NULL PRIMARY KEY, NOMBRE VARCHAR(120) NOT NULL, EMAIL VARCHAR(160) NOT NULL UNIQUE, PASSWORD_HASH VARCHAR(255) NOT NULL, ROL VARCHAR(20) NOT NULL CHECK (ROL IN ('DUENO','BIBLIOTECARIO','RECLAMADOR')), ACTIVO BOOLEAN DEFAULT TRUE NOT NULL, CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, UPDATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL);
CREATE TABLE LIBROS (ID BIGINT NOT NULL PRIMARY KEY, CODIGO VARCHAR(40) NOT NULL UNIQUE, TITULO VARCHAR(250) NOT NULL, TITULO_NORMALIZADO VARCHAR(250) NOT NULL UNIQUE, AUTOR VARCHAR(180) NOT NULL, ANIO_IMPRESION SMALLINT NOT NULL CHECK (ANIO_IMPRESION BETWEEN 1 AND EXTRACT(YEAR FROM CURRENT_DATE)), ESTADO VARCHAR(15) DEFAULT 'DISPONIBLE' NOT NULL CHECK (ESTADO IN ('DISPONIBLE','PRESTADO','INACTIVO')), ACTIVO BOOLEAN DEFAULT TRUE NOT NULL, CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, UPDATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL);
CREATE TABLE LECTORES (ID BIGINT NOT NULL PRIMARY KEY, DNI CHAR(8) NOT NULL UNIQUE CHECK (DNI SIMILAR TO '[0-9]{8}'), NOMBRE VARCHAR(180) NOT NULL, DIRECCION VARCHAR(250) NOT NULL, TELEFONO VARCHAR(20) NOT NULL, ACTIVO BOOLEAN DEFAULT TRUE NOT NULL, CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, UPDATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL);
CREATE TABLE PRESTAMOS (ID BIGINT NOT NULL PRIMARY KEY, LIBRO_ID BIGINT NOT NULL REFERENCES LIBROS(ID), LECTOR_ID BIGINT NOT NULL REFERENCES LECTORES(ID), FECHA_PRESTAMO DATE NOT NULL, FECHA_VENCIMIENTO DATE NOT NULL, FECHA_DEVOLUCION DATE, ESTADO VARCHAR(15) NOT NULL CHECK (ESTADO IN ('ACTIVO','DEVUELTO')), DIAS_ATRASO INTEGER DEFAULT 0 NOT NULL, MULTA_MONTO NUMERIC(10,2) DEFAULT 0 NOT NULL, MULTA_ESTADO VARCHAR(15) DEFAULT 'NO_APLICA' NOT NULL CHECK (MULTA_ESTADO IN ('NO_APLICA','PENDIENTE','PAGADA','ANULADA')), FECHA_PAGO DATE, PAGO_REGISTRADO_POR_USUARIO_ID BIGINT REFERENCES USUARIOS(ID), REGISTRADO_POR_USUARIO_ID BIGINT NOT NULL REFERENCES USUARIOS(ID), CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, UPDATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, ACTIVO_KEY COMPUTED BY (CASE WHEN ESTADO='ACTIVO' THEN LIBRO_ID ELSE NULL END));
CREATE TABLE ORDENES_RECLAMO (ID BIGINT NOT NULL PRIMARY KEY, PRESTAMO_ID BIGINT NOT NULL REFERENCES PRESTAMOS(ID), LECTOR_ID BIGINT NOT NULL REFERENCES LECTORES(ID), DIRECCION_SNAPSHOT VARCHAR(250) NOT NULL, TELEFONO_SNAPSHOT VARCHAR(20) NOT NULL, ESTADO VARCHAR(25) NOT NULL CHECK (ESTADO IN ('PENDIENTE','ASIGNADA','EN_RUTA','VISITADA_EXITOSA','VISITADA_FALLIDA','CANCELADA')), ASIGNADO_A_USUARIO_ID BIGINT REFERENCES USUARIOS(ID), FECHA_ASIGNACION TIMESTAMP, FECHA_VISITA TIMESTAMP, RESULTADO VARCHAR(40), OBSERVACIONES BLOB SUB_TYPE TEXT, EVIDENCIA_URL VARCHAR(500), INTENTOS INTEGER DEFAULT 0 NOT NULL, CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, UPDATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, ABIERTA_KEY COMPUTED BY (CASE WHEN ESTADO IN ('PENDIENTE','ASIGNADA','EN_RUTA') THEN PRESTAMO_ID ELSE NULL END));
CREATE TABLE NOTIFICACIONES (ID BIGINT NOT NULL PRIMARY KEY, LECTOR_ID BIGINT REFERENCES LECTORES(ID), PRESTAMO_ID BIGINT REFERENCES PRESTAMOS(ID), CANAL VARCHAR(20) NOT NULL CHECK (CANAL IN ('EMAIL','WHATSAPP','SMS','INTERNO')), DESTINO VARCHAR(160) NOT NULL, ASUNTO VARCHAR(200), CUERPO BLOB SUB_TYPE TEXT, ESTADO VARCHAR(15) NOT NULL CHECK (ESTADO IN ('PENDIENTE','ENVIADA','FALLIDA')), ERROR_DETALLE VARCHAR(500), CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE CONFIGURACION (CLAVE VARCHAR(40) NOT NULL PRIMARY KEY, VALOR VARCHAR(160) NOT NULL, DESCRIPCION VARCHAR(250));
CREATE TABLE AUDITORIA (ID BIGINT NOT NULL PRIMARY KEY, USUARIO_ID BIGINT REFERENCES USUARIOS(ID), ACCION VARCHAR(40) NOT NULL, ENTIDAD VARCHAR(40) NOT NULL, ENTIDAD_ID BIGINT, DETALLE BLOB SUB_TYPE TEXT, CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
